package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.StringUtils;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Attribute_getValue_TriageGen1Test {

    @Test
    public void testGetValue() {
        Attribute attr = new Attribute("key", "value");
        assertEquals("value", attr.getValue());
    }

    @Test
    public void testGetValueNull() {
        Attribute attr = new Attribute("key", null);
        assertEquals("", attr.getValue());
    }

    @Test
    public void testGetValueEmptyString() {
        Attribute attr = new Attribute("key", "");
        assertEquals("", attr.getValue());
    }

    @Test
    public void testGetValueNullValue() {
        Attribute attr = new Attribute("key", null, new Attributes());
        assertEquals("", attr.getValue());
    }

    @Test
    public void testGetValueEmptyStringValue() {
        Attribute attr = new Attribute("key", "", new Attributes());
        assertEquals("", attr.getValue());
    }

    @Test
    public void testEquals() {
        Attribute attr1 = new Attribute("key", "value");
        Attribute attr2 = new Attribute("key", "value");
        assertEquals(attr1, attr2);
    }

    @Test
    public void testEqualsDiffValue() {
        Attribute attr1 = new Attribute("key", "value");
        Attribute attr2 = new Attribute("key", "otherValue");
        assertNotEquals(attr1, attr2);
    }

    @Test
    public void testEqualsDiffKey() {
        Attribute attr1 = new Attribute("key", "value");
        Attribute attr2 = new Attribute("otherKey", "value");
        assertNotEquals(attr1, attr2);
    }

    @Test
    public void testHashCode() {
        Attribute attr1 = new Attribute("key", "value");
        Attribute attr2 = new Attribute("key", "value");
        assertEquals(attr1.hashCode(), attr2.hashCode());
    }

    @Test
    public void testHashCodeDiffValue() {
        Attribute attr1 = new Attribute("key", "value");
        Attribute attr2 = new Attribute("key", "otherValue");
        assertNotEquals(attr1.hashCode(), attr2.hashCode());
    }

    @Test
    public void testHashCodeDiffKey() {
        Attribute attr1 = new Attribute("key", "value");
        Attribute attr2 = new Attribute("otherKey", "value");
        assertNotEquals(attr1.hashCode(), attr2.hashCode());
    }

    @Test
    public void testClone() {
        Attribute attr = new Attribute("key", "value");
        Attribute clonedAttr = attr.clone();
        assertEquals(attr, clonedAttr);
    }

    @Test
    public void testCloneDiffValue() {
        Attribute attr = new Attribute("key", "value");
        Attribute clonedAttr = attr.clone();
        clonedAttr.setValue("otherValue");
        assertNotEquals(attr, clonedAttr);
    }

    @Test
    public void testCloneDiffKey() {
        Attribute attr = new Attribute("key", "value");
        Attribute clonedAttr = attr.clone();
        clonedAttr.setKey("otherKey");
        assertNotEquals(attr, clonedAttr);
    }
}
